{
  "lines": [
    {
      "id": "plan.full_weeks",
      "tiers": [
        {
          "id": "plan.full_weeks:t1",
          "title": "Первые шорохи плана",
          "phrase": "В твоей копилке 2 недели, в каждой — хотя бы одна полностью выполненная исходная тренировка. Хомяк-архивариус довольно шуршит.",
          "imagePrompt": "A tuft-haired hamster archivist lowers two rolled workout plans into a small open filing crate, standing on tiptoe with puffed cheeks. The rolls lean together while the hamster steadies the crate with one hind paw.",
          "fishMarkup": "[warm]В твоей копилке 2 недели, в каждой — хотя бы одна полностью выполненная исходная тренировка. <soft>Хомяк-архивариус довольно шуршит.</soft>",
          "audioText": "В твоей копилке 2 недели, в каждой — хотя бы одна полностью выполненная исходная тренировка. Хомяк-архивариус довольно шуршит."
        },
        {
          "id": "plan.full_weeks:t2",
          "title": "Тележка полных недель",
          "phrase": "Накоплено 6 недель, в каждой ты полностью выполнил хотя бы одну исходную тренировку. Хомяк выкатил тележку: папки пошли оптом.",
          "imagePrompt": "A tuft-haired hamster archivist pushes a low filing cart stacked with six rolled workout plans. It braces both paws against the handle while one hind foot rides the cart, turning a careful delivery into a tiny scooter trip.",
          "fishMarkup": "[confident]Накоплено 6 недель, в каждой ты полностью выполнил хотя бы одну исходную тренировку. [playful]Хомяк выкатил тележку: папки пошли оптом.",
          "audioText": "Накоплено 6 недель, в каждой ты полностью выполнил хотя бы одну исходную тренировку. Хомяк выкатил тележку: папки пошли оптом."
        },
        {
          "id": "plan.full_weeks:t3",
          "title": "Архив за щеками",
          "phrase": "Ты накопил 12 недель с хотя бы одной полностью выполненной исходной тренировкой в каждой. Хомяк открыл архив. Запасной — за щеками.",
          "imagePrompt": "A tuft-haired hamster archivist stands before an open cabinet packed with rolled workout plans. Its enormous puffed cheeks each unfold into a miniature filing drawer, and it calmly files one last roll into this ridiculous backup archive.",
          "fishMarkup": "[triumphant]Ты накопил 12 недель с хотя бы одной полностью выполненной исходной тренировкой в каждой. Хомяк открыл архив. <slow>Запасной — за щеками.</slow>",
          "audioText": "Ты накопил 12 недель с хотя бы одной полностью выполненной исходной тренировкой в каждой. Хомяк открыл архив. Запасной — за щеками."
        }
      ]
    },
    {
      "id": "plan.plan_streak",
      "tiers": [
        {
          "id": "plan.plan_streak:t1",
          "title": "Первый пых по плану",
          "phrase": "За 2 недели подряд ты каждую неделю полностью выполнил хотя бы одну исходную тренировку. Чайник-паровоз дал первый довольный пых.",
          "imagePrompt": "A squat kettle locomotive pulls two coupled carriages along a short curve of track. Its spout releases a single plump puff of steam, while the tilted lid reveals a tiny empty driver's cab with a lever waiting inside.",
          "fishMarkup": "[warm]За 2 недели подряд ты каждую неделю полностью выполнил хотя бы одну исходную тренировку. Чайник-паровоз дал первый <soft>довольный пых.</soft>",
          "audioText": "За 2 недели подряд ты каждую неделю полностью выполнил хотя бы одну исходную тренировку. Чайник-паровоз дал первый довольный пых."
        },
        {
          "id": "plan.plan_streak:t2",
          "title": "Рейс для печеньки",
          "phrase": "У тебя 4 недели подряд с хотя бы одной полностью выполненной исходной тренировкой в каждой. Чайник-паровоз набрал ход, печенька ждёт посадки.",
          "imagePrompt": "A squat kettle locomotive draws four coupled carriages past a tiny platform. An eager biscuit with little arms and legs reaches for the cab handrail, one foot raised toward the step, as steam curls from the kettle spout.",
          "fishMarkup": "[confident]У тебя 4 недели подряд с хотя бы одной полностью выполненной исходной тренировкой в каждой. [playful]Чайник-паровоз набрал ход, печенька ждёт посадки.",
          "audioText": "У тебя 4 недели подряд с хотя бы одной полностью выполненной исходной тренировкой в каждой. Чайник-паровоз набрал ход, печенька ждёт посадки."
        },
        {
          "id": "plan.plan_streak:t3",
          "title": "Крошечный машинист экспресса",
          "phrase": "У тебя 8 недель подряд, в каждой — хотя бы одна полностью выполненная исходная тренировка. Чайник-паровоз стал экспрессом. Машинист — печенька.",
          "imagePrompt": "A squat kettle locomotive leads eight coupled carriages around a sweeping bend. Beneath its flipped-open lid, a biscuit driver grips an oversized control lever with both arms, shedding a few crumbs onto the cab floor as the spout whistles.",
          "fishMarkup": "[triumphant]У тебя 8 недель подряд, в каждой — хотя бы одна полностью выполненная исходная тренировка. Чайник-паровоз стал экспрессом. <slow>Машинист — печенька.</slow>",
          "audioText": "У тебя 8 недель подряд, в каждой — хотя бы одна полностью выполненная исходная тренировка. Чайник-паровоз стал экспрессом. Машинист — печенька."
        }
      ]
    }
  ]
}
